function repeatsName(entries: readonly TreeEntry[]): boolean {
	return new Set(entries.map((entry) => entry.path.toString("latin1"))).size !== entries.length;
}

for (const [changeset, oid] of seen) {
	const now = folders.get(changeset);
	if (now === undefined) value.absent.push(changeset);
	else if (now !== oid) value.changed.push(changeset);
	else if (value.deferred.length > 0) value.deferred.push(changeset);
	else {
		const verdict = await StateTree.judgeFolder(this.#repository, changeset, now, judged, spent, deadline);
		value[verdict === "clean" ? "removed" : verdict === "stray" ? "strays" : "deferred"].push(changeset);
	}
}
if (tip === undefined || value.removed.length === 0) return { value };
const commit = await this.#repository.withoutFolders(tip, value.removed, deadline);
if (!(await StateTree.removesOnly(this.#repository, tip, commit, deadline)))
	throw new RecordError(
		"unreachable",
		`the commit retiring ${value.removed.join(", ")} changes more of ${this.#branch} than it removes; nothing was pushed`,
	);
return { commit, value };

async withoutFolders(parent: string, names: readonly string[], deadline: Deadline): Promise<string> {
	const root = await this.#childrenWithin(parent, deadline);
	const folder = root.find((entry) => entry.path.toString("latin1") === "changesets" && entry.type === "tree");
	if (folder === undefined) throw unreachable(`${parent} holds no changesets folder in ${this.path}`);
	const gone = new Set(names);
	const kept = (await this.#childrenWithin(folder.oid, deadline)).filter(
		(entry) => !gone.has(entry.path.toString("latin1")),
	);
	const changesets = kept.length === 0 ? undefined : await this.#mktree(kept, deadline);
	const top = root.flatMap((entry) =>
		entry !== folder ? [entry] : changesets === undefined ? [] : [{ ...entry, oid: changesets }],
	);
	const tree = await this.#mktree(top, deadline);
	return (await this.#succeed(["commit-tree", tree, "-p", parent, "-m", "melian: retire"], deadline)).trim();
}

// Retiring a disposed changeset removes its mark too, so a later add is accepted rather than refused as disposed.
it("takes a disposed changeset's mark with it, so an add starts it afresh", async () => {
	const store = await seeded();
	await store.dispose(changeset);
	await expect(store.add([check("late")])).rejects.toMatchObject({ code: "disposed" });
	await store.retire(new Map([[changeset, (await store.folders()).get(changeset)!]]));
	await store.add([check("late")]);
	expect(keys(await store.list(changeset))).toEqual(["late"]);
});
